const p=(key,label,min,max,value)=>({key,label,min,max,value,step:1});
export const MATERIAL_EFFECTS={lcdphoto:{name:'液晶屏翻拍',cat:'复古',icon:'▥',desc:'RGB 子像素栅格、屏幕亮度不均与近摄柔化',params:[p('pitch','点距',2,8,3),p('amount','栅格强度',0,100,72)]},digital2008:{name:'旧数码压缩',cat:'摄影',icon:'▧',desc:'低清采样、色阶压缩、暗部偏色与轻微失焦',params:[p('resolution','长边采样',180,1000,480),p('amount','退化程度',0,100,80)]}};
export function applyMaterial(c,e){const w=c.width,h=c.height,x=c.getContext('2d'),m=e.params.amount/100;if(!m)return c;const z=document.createElement('canvas');z.width=w;z.height=h;z.getContext('2d').drawImage(c,0,0);if(e.type==='lcdphoto'){const sm=document.createElement('canvas');sm.width=Math.max(1,Math.min(w,Math.max(1,Math.round(1200/(e.params.pitch*2)))));sm.height=Math.max(1,Math.round(sm.width*h/w));sm.getContext('2d').drawImage(c,0,0,sm.width,sm.height);x.save();x.clearRect(0,0,w,h);x.imageSmoothingEnabled=false;x.drawImage(sm,0,0,w,h);x.restore();}if(e.type==='digital2008'){const sm=document.createElement('canvas'),s=Math.min(1,e.params.resolution/Math.max(w,h));sm.width=Math.max(1,Math.round(w*s));sm.height=Math.max(1,Math.round(h*s));sm.getContext('2d').drawImage(c,0,0,sm.width,sm.height);x.save();x.clearRect(0,0,w,h);x.filter=`blur(${w/1200*.65}px)`;x.drawImage(sm,0,0,w,h);x.restore();}const im=x.getImageData(0,0,w,h),a=im.data,orig=z.getContext('2d').getImageData(0,0,w,h).data;for(let y=0;y<h;y++)for(let xx=0;xx<w;xx++){const i=(y*w+xx)*4;if(e.type==='lcdphoto'){const pitch=Math.max(2,Math.round(e.params.pitch*w/1200)),gx=(xx/pitch)%1,gy=(y/pitch)%1,grid=gx>.78||gy>.72?.52:1,fall=1-.22*((xx/w-.45)**2+(y/h-.4)**2),n=(Math.sin(xx*74.7+y*13.1)*437.1)%1;for(let k=0;k<3;k++){const sub=(Math.floor(gx*3)===k?1:.78);a[i+k]*=1-m+m*grid*sub*fall;a[i+k]+=n*m*5*Math.min(1,orig[i+k]/80);}}else{const n=Math.sin(xx*17.3+y*71.8)*2;for(let k=0;k<3;k++){const v=Math.round(a[i+k]/5)*5+n+(k===0?2:k===1?3:-4);a[i+k]=orig[i+k]*(1-m)+v*m;}}a[i+3]=orig[i+3];}x.putImageData(im,0,0);return c;}
